<content>import { useState, useEffect } from 'react';
import { motion, AnimatePresence } from 'framer-motion';
import { useNavigate } from 'react-router-dom';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Label } from '@/components/ui/label';
import { useStore } from '@/store/useStore';
import { useToast } from '@/hooks/use-toast';
import { 
  magpiePayment, 
  PAYMENT_METHODS, 
  CheckoutSessionRequest,
  CheckoutSessionResponse,
  PaymentStatus
} from '@/lib/magpie';
import { 
  CreditCard, 
  Trash2, 
  Plus, 
  Minus, 
  ShoppingCart, 
  User, 
  Mail, 
  Phone,
  AlertCircle,
  CheckCircle,
  Loader2,
  Copy,
  ExternalLink,
  Clock
} from 'lucide-react';
import { 
  AnimatedPage, 
  AnimatedCard, 
  fadeInUp, 
  staggerContainer,
  messageVariants,
  cartItemVariants
} from '@/components/AnimatedComponents';

export default function Checkout() {
  const navigate = useNavigate();
  const { cart, updateCartQuantity, removeFromCart, clearCart, getCartTotal, addOrder } = useStore();
  const { toast } = useToast();

  const [customerInfo, setCustomerInfo] = useState({
    name: '',
    email: '',
    phone: ''
  });
  const [selectedPaymentMethod, setSelectedPaymentMethod] = useState('gcash');
  const [processing, setProcessing] = useState(false);
  const [errors, setErrors] = useState<Record<string, string>>({});

  // Checkout session state
  const [checkoutSession, setCheckoutSession] = useState<CheckoutSessionResponse | null>(null);
  const [paymentStatus, setPaymentStatus] = useState<PaymentStatus | null>(null);
  const [checkingStatus, setCheckingStatus] = useState(false);
  const [sessionExpired, setSessionExpired] = useState(false);

  const subtotal = getCartTotal();
  const selectedMethod = PAYMENT_METHODS.find(method => method.id === selectedPaymentMethod);
  const fee = selectedMethod ? magpiePayment.calculateFee(subtotal, selectedPaymentMethod) : 0;
  const total = subtotal + fee;

  useEffect(() => {
    if (cart.length === 0) {
      navigate('/shop');
    }
  }, [cart.length, navigate]);

  // Check for session expiration
  useEffect(() => {
    if (checkoutSession?.expiresAt) {
      const expirationTime = new Date(checkoutSession.expiresAt).getTime();
      const now = Date.now();

      if (now >= expirationTime) {
        setSessionExpired(true);
        return;
      }

      const timeoutId = setTimeout(() => {
        setSessionExpired(true);
        toast({
          title: "Session Expired",
          description: "Your checkout session has expired. Please start a new payment.",
          variant: "destructive",
        });
      }, expirationTime - now);

      return () => clearTimeout(timeoutId);
    }
  }, [checkoutSession?.expiresAt, toast]);

  const validateForm = () => {
    const newErrors: Record<string, string> = {};

    if (!customerInfo.name.trim()) {
      newErrors.name = 'Name is required';
    }
    if (!customerInfo.email.trim()) {
      newErrors.email = 'Email is required';
    } else if (!/\S+@\S+\.\S+/.test(customerInfo.email)) {
      newErrors.email = 'Please enter a valid email';
    }
    if (!customerInfo.phone.trim()) {
      newErrors.phone = 'Phone number is required';
    }

    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleInputChange = (field: string, value: string) => {
    setCustomerInfo(prev => ({ ...prev, [field]: value }));
    if (errors[field]) {
      setErrors(prev => ({ ...prev, [field]: '' }));
    }
  };

  const copyToClipboard = (text: string) => {
    navigator.clipboard.writeText(text);
    toast({
      title: "Copied!",
      description: "Text copied to clipboard",
    });
  };

  const createCheckoutSession = async () => {
    console.log('🛒 Creating checkout session...');

    if (!validateForm()) {
      toast({
        title: "Please fill in all required fields",
        description: "Complete your information to proceed with payment.",
        variant: "destructive",
      });
      return;
    }

    setProcessing(true);
    setCheckoutSession(null);
    setPaymentStatus(null);
    setSessionExpired(false);

    try {
      const sessionRequest: CheckoutSessionRequest = {
        amount: subtotal,
        currency: 'PHP',
        description: `DRL Solutions - ${cart.length} item(s)`,
        customer: {
          email: customerInfo.email,
          name: customerInfo.name,
          phone: customerInfo.phone
        },
        items: cart.map(item => ({
          name: item.product.name,
          quantity: item.quantity,
          price: item.product.price,
          description: `${item.product.name} - Digital Service`
        })),
        paymentMethod: selectedPaymentMethod,
        successUrl: `${window.location.origin}/order-success`,
        cancelUrl: `${window.location.origin}/checkout`,
        metadata: {
          customer_name: customerInfo.name,
          customer_email: customerInfo.email,
          customer_phone: customerInfo.phone,
          items_count: cart.length.toString(),
          source: 'drl-solutions-checkout'
        }
      };

      console.log('🚀 Creating checkout session with request:', sessionRequest);

      const response = await magpiePayment.createCheckoutSession(sessionRequest);
      console.log('📨 Checkout session response:', response);

      if (response.success && response.sessionId) {
        setCheckoutSession(response);

        // Create order record with pending status
        const order = {
          id: response.sessionId,
          user_id: 'guest',
          total_amount: total,
          status: 'pending' as const,
          payment_intent_id: response.paymentIntentId || response.sessionId,
          created_at: new Date().toISOString(),
          items: cart.map(item => ({
            id: `item_${Date.now()}_${Math.random()}`,
            product_id: item.product.id,
            quantity: item.quantity,
            price: item.product.price,
            product: item.product
          }))
        };

        addOrder(order);

        toast({
          title: "Checkout Session Created!",
          description: response.checkoutUrl 
            ? "Click the payment button to complete your purchase."
            : "Follow the payment instructions to complete your purchase.",
        });

      } else {
        throw new Error(response.error || 'Failed to create checkout session');
      }
    } catch (error) {
      console.error('❌ Checkout session creation failed:', error);

      let errorMessage = 'Failed to create checkout session. Please try again.';

      if (error instanceof Error) {
        errorMessage = error.message;
      }

      toast({
        title: "Checkout Failed",
        description: errorMessage,
        variant: "destructive",
      });

    } finally {
      setProcessing(false);
    }
  };

  const checkPaymentStatus = async () => {
    if (!checkoutSession?.sessionId) return;

    setCheckingStatus(true);

    try {
      console.log('🔍 Checking payment status for session:', checkoutSession.sessionId);

      const status = await magpiePayment.getPaymentStatus(checkoutSession.sessionId);
      console.log('📊 Payment status:', status);

      setPaymentStatus(status);

      if (status.success && status.status === 'completed') {
        // Payment completed successfully
        toast({
          title: "Payment Completed!",
          description: "Your payment has been processed successfully.",
        });

        // Clear cart and navigate to success page
        clearCart();
        navigate(`/order-success/${checkoutSession.sessionId}`, {
          state: {
            paymentMethod: selectedPaymentMethod,
            paymentId: status.paymentId,
            amount: status.amount || total,
            verified: true,
            paidAt: status.paidAt
          }
        });

      } else if (status.status === 'failed') {
        toast({
          title: "Payment Failed",
          description: status.error || "Your payment could not be processed.",
          variant: "destructive",
        });

      } else if (status.status === 'cancelled') {
        toast({
          title: "Payment Cancelled",
          description: "Your payment was cancelled.",
          variant: "destructive",
        });

      } else {
        toast({
          title: "Payment Pending",
          description: "Your payment is still being processed. Please wait a moment and check again.",
        });
      }
    } catch (error) {
      console.error('❌ Payment status check failed:', error);
      toast({
        title: "Unable to Check Payment Status",
        description: "Please try again or contact support if payment was completed.",
        variant: "destructive",
      });
    } finally {
      setCheckingStatus(false);
    }
  };

  const openPaymentGateway = () => {
    if (checkoutSession?.checkoutUrl) {
      window.open(checkoutSession.checkoutUrl, '_blank', 'noopener,noreferrer');
      toast({
        title: "Payment Gateway Opened",
        description: "Complete your payment in the new tab, then check status here.",
        duration: 5000,
      });
    }
  };

  const resetCheckout = () => {
    setCheckoutSession(null);
    setPaymentStatus(null);
    setSessionExpired(false);
    setErrors({});
  };

  if (cart.length === 0) {
    return null;
  }

  const hasActiveSession = checkoutSession && !sessionExpired;
  const isPaymentCompleted = paymentStatus?.status === 'completed';

  return (
    <AnimatedPage className="bg-white">
      <div className="container mx-auto px-4 py-16">
        <motion.div
          variants={staggerContainer}
          initial="initial"
          animate="animate"
          className="max-w-6xl mx-auto"
        >
          {/* Header */}
          <motion.div variants={fadeInUp} className="text-center mb-12">
            <h1 className="text-4xl md:text-5xl font-bold text-black mb-4">
              Checkout
            </h1>
            <p className="text-xl text-gray-600">
              Complete your order and start your project
            </p>
          </motion.div>

          {/* Session Status Alerts */}
          <AnimatePresence>
            {sessionExpired && (
              <motion.div
                initial={{ opacity: 0, y: -20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                className="mb-8"
              >
                <Card className="bg-red-50 border-red-200">
                  <CardContent className="p-6">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-3">
                        <Clock className="h-6 w-6 text-red-600" />
                        <div>
                          <h3 className="text-red-800 font-medium">Session Expired</h3>
                          <p className="text-red-700 text-sm">Your checkout session has expired. Please start a new payment.</p>
                        </div>
                      </div>
                      <Button
                        onClick={resetCheckout}
                        className="bg-red-600 hover:bg-red-700 text-white"
                      >
                        Start New Payment
                      </Button>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            )}

            {hasActiveSession && !isPaymentCompleted && (
              <motion.div
                initial={{ opacity: 0, y: -20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                className="mb-8"
              >
                <Card className="bg-blue-50 border-blue-200">
                  <CardContent className="p-6">
                    <div className="flex items-center justify-between">
                      <div className="flex items-center space-x-3">
                        <CheckCircle className="h-6 w-6 text-blue-600" />
                        <div>
                          <h3 className="text-blue-800 font-medium">Payment Session Active</h3>
                          <p className="text-blue-700 text-sm">
                            {checkoutSession?.checkoutUrl 
                              ? "Click 'Pay Now' to complete your payment, then check status."
                              : "Follow the payment instructions, then check status."
                            }
                          </p>
                        </div>
                      </div>
                      <div className="flex space-x-2">
                        {checkoutSession?.checkoutUrl && (
                          <Button
                            onClick={openPaymentGateway}
                            className="bg-blue-600 hover:bg-blue-700 text-white"
                          >
                            <ExternalLink className="mr-2 h-4 w-4" />
                            Pay Now
                          </Button>
                        )}
                        <Button
                          onClick={checkPaymentStatus}
                          disabled={checkingStatus}
                          variant="outline"
                          className="border-blue-300"
                        >
                          {checkingStatus ? (
                            <>
                              <Loader2 className="mr-2 h-4 w-4 animate-spin" />
                              Checking...
                            </>
                          ) : (
                            'Check Status'
                          )}
                        </Button>
                      </div>
                    </div>
                  </CardContent>
                </Card>
              </motion.div>
            )}

            {paymentStatus && paymentStatus.status !== 'completed' && (
              <motion.div
                initial={{ opacity: 0, y: -20 }}
                animate={{ opacity: 1, y: 0 }}
                exit={{ opacity: 0, y: -20 }}
                className="mb-8"
              >
                <Card className={`${
                  paymentStatus.status === 'failed' ? 'bg-red-50 border-red-200' :
                  paymentStatus.status === 'cancelled' ? 'bg-gray-50 border-gray-200' :
                  'bg-yellow-50 border-yellow-200'
                }`}>
                  <CardContent className="p-6">
                    <div className="flex items-center space-x-3">
                      <AlertCircle className={`h-6 w-6 ${
                        paymentStatus.status === 'failed' ? 'text-red-600' :
                        paymentStatus.status === 'cancelled' ? 'text-gray-600' :
                        'text-yellow-600'
                      }`} />
                      <div>
                        <h3 className={`font-medium ${
                          paymentStatus.status === 'failed' ? 'text-red-800' :
                          paymentStatus.status === 'cancelled' ? 'text-gray-800' :
                          'text-yellow-800'
                        }`}>
                          Payment {paymentStatus.status.charAt(0).toUpperCase() + paymentStatus.status.slice(1)}
                        </h3>
                        <p className={`text-sm ${
