      console.error('❌ Payment error:', error);

      let errorMessage = 'Payment processing failed. Please try again.';

      if (error instanceof Error) {
        errorMessage = error.message;
      }

      toast({
        title: "Payment Failed",
        description: errorMessage,
        variant: "destructive",
