                          >
                            <Loader2 className="mr-2 h-5 w-5 animate-spin" />
                            Processing Payment...
                          </motion.div>
                        ) : awaitingPayment ? (
                          <motion.div
                            key="awaiting"
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            className="flex items-center"
                          >
                            <AlertCircle className="mr-2 h-5 w-5" />
                            Complete Payment First
                          </motion.div>
                        ) : (
                          <motion.div
                            key="pay"
                            initial={{ opacity: 0 }}
                            animate={{ opacity: 1 }}
                            exit={{ opacity: 0 }}
                            className="flex items-center"
                          >
                            <CreditCard className="mr-2 h-5 w-5" />
                            Pay ₱{total.toLocaleString()}
                          </motion.div>
                        )}
                      </AnimatePresence>
                    </Button>
                  </motion.div>

                  {/* Security Notice */}
                  <motion.div
                    initial={{ opacity: 0 }}
                    animate={{ opacity: 1 }}
                    transition={{ delay: 1 }}
                    className="text-center text-sm text-gray-500"
                  >
                    <div className="flex items-center justify-center space-x-2">
                      <CheckCircle className="h-4 w-4 text-green-500" />
                      <span>Secure payment powered by Magpie.im</span>
                    </div>
                  </motion.div>
                </CardContent>
              </Card>
            </AnimatedCard>
          </div>
        </motion.div>
      </div>
    </AnimatedPage>
  );
}</content>
