                      </div>
                      <AnimatePresence>
                        {errors.email && (
                          <motion.p
                            variants={messageVariants}
                            initial="initial"
                            animate="animate"
                            exit="exit"
                            className="text-red-500 text-sm mt-1 flex items-center"
                          >
                            <AlertCircle className="h-4 w-4 mr-1" />
                            {errors.email}
                          </motion.p>
